SELECT TRIGGER_NAME,EVENT_MANIPULATION,ACTION_TIMING FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() ORDER BY TRIGGER_NAME;
SET @p2_ok=(SELECT COUNT(*)=1 FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='trg_accounts_ai_audit' AND LOWER(EVENT_OBJECT_TABLE)='accounts' AND EVENT_MANIPULATION='INSERT' AND ACTION_TIMING='AFTER');
CALL bank_lab.sp_assert_true(DATABASE(),'inventory trg_accounts_ai_audit',@p2_ok,'Expected audit contract');
